class Solution:
    def isSubPath(self, head, root) -> bool:
        def match(lst, tree):
            if not lst:
                return True
            if not tree:
                return False
            if lst.val != tree.val:
                return False
            return match(lst.next, tree.left) or match(lst.next, tree.right)

        if not root:
            return False
        return match(head, root) or self.isSubPath(head, root.left) or self.isSubPath(head, root.right)

